const trigger = $('Intent Webhook').item.json.body;
let parsed;
try { parsed = JSON.parse($json.choices?.[0]?.message?.content ?? '{}'); } catch { parsed = {}; }
const message = String(trigger.message ?? '');
const forcedIntent = ['CONFIRMING_ORDER','CREATING_PAYMENT'].includes(String(trigger.current_state ?? '')) && /(confirmo|confirmar|pode seguir|sim|fechar|finalizar)/i.test(message)
  ? 'BUY_TICKET'
  : (parsed.intent ?? 'OTHER');
return [{ json: { ...trigger, intent: forcedIntent, confidence: Number(parsed.confidence ?? 0), entities: parsed.entities ?? {} } }];

const input = $json.body;
const text = String(input.message ?? '').toLowerCase();
const cleanText = String(input.message ?? '').trim();

let intent = 'OTHER';
if (/compr|passagem|viajar|bilhete/.test(text)) intent = 'BUY_TICKET';
if (['CONFIRMING_ORDER','CREATING_PAYMENT'].includes(String(input.current_state ?? '')) && /(confirmo|confirmar|pode seguir|sim|fechar|finalizar)/i.test(text)) {
  intent = 'BUY_TICKET';
}
else if (/hor[aá]rio|sa[ií]da|barco/.test(text)) intent = 'ASK_SCHEDULES';
else if (/pre[cç]o|valor|quanto custa/.test(text)) intent = 'ASK_PRICES';
else if (/atendente|humano|ajuda/.test(text)) intent = 'HUMAN_HELP';

let origin = null;
let destination = null;

const payload = input.state_payload ?? {};

// Case 1: de [origem] para/até [destino]
const deParaMatch = text.match(/(?:de\s+)?([a-záàâãéèêíïóôõöúç ]+?)\s+(?:para|até|e|a|x)\s+([a-záàâãéèêíïóôõöúç ]+?)(?=\s+(?:amanhã|amanha|hoje|dia|em|\d{1,2}[\/-]\d{1,2})|$)/i);
if (deParaMatch) {
  origin = deParaMatch[1].trim();
  destination = deParaMatch[2].trim();
}

// Case 2: [origem], [destino]
const commaMatch = text.match(/^\s*([a-záàâãéèêíïóôõöúç ]+?)\s*[,-\/]\s*([a-záàâãéèêíïóôõöúç ]+?)\s*(?:,|$)/i);
if (commaMatch && !origin) {
  origin = commaMatch[1].trim();
  destination = commaMatch[2].trim();
}

const cpf = text.match(/\b(\d{11}|\d{3}\.?\d{3}\.?\d{3}-?\d{2})\b/);
const textWithoutCpf = cpf ? text.replace(cpf[0], '') : text;
const date = textWithoutCpf.match(/\b(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2,4}))?\b/);
const name = text.match(/(?:meu nome (?:é|e)|passageiro(?:a)?|nome)\s*[:,-]?\s*([a-záàâãéèêíïóôõöúç ]{3,80})/i);

// Case 3/4: Fallbacks for COLLECTING_TRIP
if (!origin && !destination && String(input.current_state) === 'COLLECTING_TRIP' && !date && !cpf) {
  const cleanStr = text.replace(/[^a-záàâãéèêíïóôõöúç ]/gi, '').trim();
  const wordsCount = cleanStr.split(/\s+/).filter(Boolean).length;

  if (wordsCount > 0 && wordsCount <= 4) {
    if (!payload.origin) {
      if (wordsCount === 2) {
        const parts = cleanStr.split(/\s+/);
        origin = parts[0];
        destination = parts[1];
      } else {
        origin = cleanStr;
      }
    } else if (!payload.destination) {
      destination = cleanStr;
    }
  }
}

const entities = {};

if (origin && destination) {
  entities.origin = origin;
  entities.destination = destination;
} else if (origin) {
  entities.origin = origin;
} else if (destination) {
  entities.destination = destination;
}

if (date) {
  const day = String(date[1]).padStart(2, '0');
  const month = String(date[2]).padStart(2, '0');
  const year = date[3] ? Number(date[3].length === 2 ? '20' + date[3] : date[3]) : new Date().getUTCFullYear();

  const dayNumber = Number(day);
  const monthNumber = Number(month);

  if (dayNumber >= 1 && dayNumber <= 31 && monthNumber >= 1 && monthNumber <= 12) {
    entities.travel_date = [year, month, day].join('-');
  }
} else if (/\bamanh[ãa]\b/.test(text)) {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + 1);
  entities.travel_date = d.toISOString().slice(0, 10);
} else if (/\bhoje\b/.test(text)) {
  entities.travel_date = new Date().toISOString().slice(0, 10);
}

if (cpf) {
  entities.passenger_cpf = cpf[1].replace(/\D/g, '');
}

if (name) {
  entities.passenger_name = name[1].replace(/\s+(?:cpf|documento).*$/i, '').trim();
} else if (String(input.current_state) === 'COLLECTING_PASSENGER' && !cpf && !date) {
  if (cleanText.length >= 3 && cleanText.length <= 80 && !cleanText.includes(' ') && !/^[0-9]+$/.test(cleanText)) {
    entities.passenger_name = cleanText;
  } else if (cleanText.length >= 3 && cleanText.length <= 80 && cleanText.split(/\s+/).length >= 2 && !/^[0-9\s]+$/.test(cleanText)) {
    entities.passenger_name = cleanText;
  }
}

return [{ json: { ...input, intent, confidence: 1, entities } }];

const allowed = ['BUY_TICKET','ASK_SCHEDULES','ASK_PRICES','HUMAN_HELP','OTHER'];
const collecting = ['COLLECTING_TRIP','COLLECTING_PASSENGER','CONFIRMING_ORDER'].includes($json.current_state);
const intent = collecting ? 'BUY_TICKET' : (allowed.includes($json.intent) ? $json.intent : 'OTHER');
const entities = $json.entities && typeof $json.entities === 'object' && !Array.isArray($json.entities) ? $json.entities : {};
for (const key of Object.keys(entities)) if (entities[key] == null || entities[key] === '') delete entities[key];
return [{ json: { ...$json, intent, confidence: Math.max(0, Math.min(1, Number($json.confidence || 0))), entities } }];
